mapper.select:
select * from sys_instrument_warn_record

    and rule_id = #{ruleId}
    and instrument_id = #{instrumentId}
    and handle_status = #{handleStatus}

mapper.update:
update sys_instrument_warn_record

    handle_status = #{handleStatus},
    handle_user_id = #{handleUserId},
    handle_time = #{handleTime},
    handle_remark = #{handleRemark}

where id = #{id}

mapper.select:
select count(*) from sys_instrument_warn_record
where rule_id = #{ruleId}
  and business_id = #{businessId}
  and handle_status = '0'
